// ---- app/controllers/auth/helpers/blockUser.js ----
const { addHours } = require('date-fns')
const HOURS_TO_BLOCK = 2

const { buildErrObject } = require('../../../middleware/utils')

/**
 * Blocks a user by setting blockExpires to the specified date based on constant HOURS_TO_BLOCK
 * @param {Object} user - user object
 */
const blockUser = (user = {}) => {
  return new Promise((resolve, reject) => {
    user.blockExpires = addHours(new Date(), HOURS_TO_BLOCK)
    user.save((err, result) => {
      if (err) {
        return reject(buildErrObject(422, err.message))
      }
      if (result) {
        return resolve(buildErrObject(409, 'BLOCKED_USER'))
      }
    })
  })
}

module.exports = { blockUser }


// ---- app/controllers/auth/helpers/checkLoginAttemptsAndBlockExpires.js ----
const { blockIsExpired } = require('./blockIsExpired')
const { buildErrObject } = require('../../../middleware/utils')

/**
 *
 * @param {Object} user - user object.
 */
const checkLoginAttemptsAndBlockExpires = (user = {}) => {
  return new Promise((resolve, reject) => {
    // Let user try to login again after blockexpires, resets user loginAttempts
    if (blockIsExpired(user)) {
      user.loginAttempts = 0
      user.save((err, result) => {
        if (err) {
          return reject(buildErrObject(422, err.message))
        }
        if (result) {
          return resolve(true)
        }
      })
    }
    // User is not blocked, check password (normal behaviour)
    resolve(true)
  })
}

module.exports = { checkLoginAttemptsAndBlockExpires }


