function checkPlaceholderSecrets(): void {
  const placeholders = Object.entries(PLACEHOLDER_SECRETS)
    .filter(([envVar, placeholder]) => process.env[envVar] === placeholder)
    .map(([envVar]) => envVar);

  if (placeholders.length === 0) {
